/**
 * FARNAVI — SINGLE TEMPLATE IDENTITY (C02)
 * The only place that turns any legacy/current template id into a real series.
 * Series ids: 2 3 4 11 12 14 22 24  (public/templates/{id})
 * Locked design comes from lib/template-design.json (generated by CHUNK 02).
 */
import { TEMPLATE_CATALOG } from "@/lib/template-catalog";
import type { Tpl as CatalogTpl } from "@/lib/template-catalog";
import designMap from "@/lib/template-design.json";
import type { SeriesId, DocKind, PageSize } from "./schema";

export type Variant = "design" | "ats";

type LockedDesign = {
  accent: string | null; deep: string | null; tint: string | null;
  ink: string; muted: string; rule: string; page: string;
  heading: string | null; body: string | null;
  columns: number; photo: boolean;
};
const DESIGN = designMap as unknown as Record<string, LockedDesign>;

export const TEMPLATE_SERIES_IDS: SeriesId[] = ["2", "3", "4", "11", "12", "14", "22", "24"];
const KNOWN: string[] = TEMPLATE_SERIES_IDS as string[];

/** Legacy ids from lib/catalog.ts -> real series + variant. Never delete: old saved docs use them. */
const LEGACY: Record<string, { series: SeriesId; variant: Variant }> = {
  "editorial-11":      { series: "11", variant: "design" },
  "prime-ats-11":      { series: "11", variant: "ats" },
  "harmonized-12":     { series: "12", variant: "design" },
  "precision-ats-12":  { series: "12", variant: "ats" },
  "calligraphic-14":   { series: "14", variant: "design" },
  "pure-ats-14":       { series: "14", variant: "ats" },
  "crest-22":          { series: "22", variant: "design" },
  "momentum-ats-22":   { series: "22", variant: "ats" },
  "cover-editorial-11":    { series: "11", variant: "design" },
  "cover-harmonized-12":   { series: "12", variant: "design" },
  "cover-calligraphic-14": { series: "14", variant: "design" },
  "cover-crest-22":        { series: "22", variant: "design" },
  "modern":     { series: "12", variant: "design" },
  "executive":  { series: "22", variant: "design" },
  "prime-ats":  { series: "11", variant: "ats" },
  "pure-ats":   { series: "14", variant: "ats" }
};

export type ResolvedTemplate = {
  series: SeriesId;
  variant: Variant;
  entry: CatalogTpl;
  design: LockedDesign | null;
};

export function resolveTemplate(
  input: string | { template?: string | null; series?: string | null } | null | undefined
): ResolvedTemplate | null {
  const raw = typeof input === "string" ? input : (input?.series ?? input?.template ?? "");
  if (!raw) return null;
  let series = "";
  let variant: Variant = "design";
  if (KNOWN.includes(raw)) series = raw;
  else if (LEGACY[raw]) { series = LEGACY[raw].series; variant = LEGACY[raw].variant; }
  else {
    const m = raw.match(/(\d+)/);
    if (m && KNOWN.includes(m[1])) { series = m[1]; variant = /ats/i.test(raw) ? "ats" : "design"; }
  }
  if (!series) return null;
  const entry = TEMPLATE_CATALOG.find((t) => t.id === series);
  if (!entry) return null;
  return { series: series as SeriesId, variant, entry, design: DESIGN[series] ?? null };
}

export const seriesEntry = (series: string): CatalogTpl | null =>
  TEMPLATE_CATALOG.find((t) => t.id === series) ?? null;

export function previewUrl(series: string, kind: DocKind = "resume", pages = 1, size: PageSize = "a4"): string | null {
  const e = seriesEntry(series);
  if (!e) return null;
  const key = kind === "resume" ? "resume-" + pages + "p-" + size : kind + "-" + size;
  return e.previews[key] ?? e.previews[kind + "-a4"] ?? Object.values(e.previews)[0] ?? null;
}

export function templateFile(series: string, kind: DocKind, size: PageSize, format: "pdf" | "docx", pages = 1) {
  const e = seriesEntry(series);
  if (!e) return null;
  return e.files.find((f) => f.doc === kind && f.size === size && f.format === format && (kind !== "resume" || f.pages === pages)) ?? null;
}

/** gdocs rows for US Letter often carry size:null in the source data — tolerate it. */
export function templateGdoc(series: string, kind: DocKind, size: PageSize, pages = 1) {
  const e = seriesEntry(series);
  if (!e) return null;
  return e.gdocs.find((g) =>
    g.doc === kind &&
    (g.size === size || (size === "letter" && g.size === null)) &&
    (kind !== "resume" || g.pages === pages)
  ) ?? null;
}

/** Shape-compatible with the legacy catalog so lib/store.tsx can swap to it in C03. */
export type EditorTemplate = {
  id: SeriesId; name: string; twoCol: boolean; pro: boolean; ats: boolean; photo: boolean;
  pages: number[]; sizes: PageSize[];
  /** @deprecated visual authority is lib/template-design.json, not these fields */
  accent: string; headingFont: string; bodyFont: string;
};

export const EDITOR_TEMPLATES: EditorTemplate[] = TEMPLATE_CATALOG
  .filter((t) => KNOWN.includes(t.id))
  .map((t) => {
    const d = DESIGN[t.id];
    return {
      id: t.id as SeriesId,
      name: t.name,
      twoCol: (d?.columns ?? t.columns) === 2,
      pro: t.tier === "premium",
      ats: t.ats,
      photo: d?.photo ?? t.photo,
      pages: t.pages,
      sizes: t.sizes as PageSize[],
      accent: d?.accent ?? "",
      headingFont: d?.heading ?? "",
      bodyFont: d?.body ?? ""
    };
  });